import "./styles.css";
export default function App() {
/* Lädt CSS-Datei und definiert die Komponente */

  return (
    /* Funktion gibt JSX (Java Script XML - Syntax) zurück */
    <div className="App">

      <h1>Aufgabe 1</h1>
      <button
        id="ButtonElement"
        /* HTML-Attribut mit einem beliebigen String als Wert. */
        onClick={(e) => console.log(e.target.id)}
        /* ist ein Event-Handler. Geschweifte Klammern wechseln von JSX zu JavaScript. */
        /* (e) => ... ist eine anonyme Arrow Funktion. React übergibt das Event-Objekt e. */
        onMouseEnter={() => console.log("Mauszeiger auf Button")}
        /* wird ausgelöst, wenn die Maus in den Button hineinfährt, resp. verlässt. */
        onMouseLeave={() => console.log("Mauszeiger nicht mehr auf Button")}
        /* wird ausgelöst, wenn die Maus den Button verlässt. */>     
        Klick mich
      </button>

      <h1>Aufgabe 2</h1>
      <input
        type="checkbox"
        /* Input wird ein Kästchen zum Anhaken. */
        onChange={(e) => console.log(e.target.checked)}
        /* onChange wird ausgelöst, sobald sich der Zustand ändert. Sowohl mit Mausklick als auch mit Tastatur */
        /* e.target.checked gibt den Wert der Checkbox in Boolean zurück (angehakt = True, ansonsten False. */
      ></input>
      
      <h1>Aufgabe 3</h1>
      <input
      /* input ohne "type=" ist ein Textfeld. */
        placeholder="Default wert"
        /* placeholder zeigt ein grauer Hilfetext, solange das Feld leer ist. */  
        onKeyDown={(e) => console.log(e.key)}
        /* onKeyDown wird bei jedem Tastendruck ausgelöst, noch bevor das Zeichen erscheint. */
        /* e.key gibt den Wert der gedrückten Taste zurück (A, B, Shift, Enter, etc.). */
      ></input>
      </div>
  );
}
